import rules_lib

def check(ctx):
    citizenship_type = ctx['citizenship_type']
    occupancy_subtype = ctx['occupancy_subtype']
    is_foreign_national = rules_lib.same(citizenship_type, 'Foreign National')

    if is_foreign_national:
        loan_purpose = ctx['loan_purpose']
        cltv_pct = ctx['cltv_pct']
        escrow_waiver_requested = ctx['escrow_waiver_requested']
        missing = rules_lib.gaps(
            citizenship_type=citizenship_type,
            occupancy_subtype=occupancy_subtype,
            loan_purpose=loan_purpose,
            cltv_pct=cltv_pct,
            escrow_waiver_requested=escrow_waiver_requested,
        )
    else:
        missing = rules_lib.gaps(
            citizenship_type=citizenship_type,
            occupancy_subtype=occupancy_subtype,
        )

    if missing:
        return rules_lib.unknown(*missing)

    if not rules_lib.same(occupancy_subtype, 'investment', 'investment property'):
        return False

    if not is_foreign_national:
        return True

    is_purchase = rules_lib.same(loan_purpose, 'purchase')
    is_refinance = rules_lib.same(
        loan_purpose,
        'refinance',
        'rate & term',
        'rate & term refinance',
        'cash-out',
        'cash-out refinance',
    )
    if not is_purchase and not is_refinance:
        return rules_lib.unknown('loan_purpose')

    cltv_limit = 70 if is_purchase else 65
    within_cltv_limit = rules_lib.band(cltv_pct, [(cltv_limit, True)], above=False)
    if within_cltv_limit is None:
        return rules_lib.unknown('cltv_pct')

    escrow_waiver = rules_lib.flag(escrow_waiver_requested)
    if escrow_waiver is None:
        return rules_lib.unknown('escrow_waiver_requested')

    return within_cltv_limit and not escrow_waiver

import rules_lib

def check(ctx):
    citizenship_type = ctx['citizenship_type']
    citizenship = rules_lib.match(citizenship_type, [
        'US Citizen', 'Permanent Resident', 'Non-Permanent Resident',
        'Foreign National', 'ITIN'
    ])
    missing = rules_lib.gaps(citizenship_type=citizenship_type)
    if missing:
        return rules_lib.unknown(*missing)
    if citizenship is None:
        return False
    if not rules_lib.same(citizenship, 'ITIN'):
        return True

    loan_amount = ctx['loan_amount']
    fico = ctx['fico']
    cltv_pct = ctx['cltv_pct']
    loan_purpose = ctx['loan_purpose']
    missing = rules_lib.gaps(
        loan_amount=loan_amount, fico=fico,
        cltv_pct=cltv_pct, loan_purpose=loan_purpose
    )
    if missing:
        return rules_lib.unknown(*missing)

    if loan_amount > 1000000 or fico < 640:
        return False

    if rules_lib.same(loan_purpose, 'purchase'):
        is_purchase = True
    elif rules_lib.same(loan_purpose, 'refinance') or rules_lib.same(
        loan_purpose, 'rate and term'
    ) or rules_lib.same(loan_purpose, 'cash-out'):
        is_purchase = False
    else:
        return rules_lib.unknown('loan_purpose')

    # Apply only the FICO tiers stated in the table; do not extend the
    # printed “FICO 700” tier to scores above 700.
    if 640 <= fico <= 659:
        max_cltv = 60
    elif 660 <= fico <= 699:
        max_cltv = 65 if is_purchase else 60
    elif fico == 700:
        max_cltv = 70 if is_purchase else 65
    else:
        max_cltv = None

    return max_cltv is None or cltv_pct <= max_cltv

import rules_lib

def check(ctx):
    bankruptcy_or_foreclosure = ctx['bankruptcy_or_foreclosure']
    missing = rules_lib.gaps(bankruptcy_or_foreclosure=bankruptcy_or_foreclosure)
    if missing:
        return rules_lib.unknown(*missing)

    applies = rules_lib.flag(bankruptcy_or_foreclosure)
    if applies is None:
        return rules_lib.unknown('bankruptcy_or_foreclosure')
    if not applies:
        return True

    months_since_bankruptcy_or_foreclosure = ctx['months_since_bankruptcy_or_foreclosure']
    missing = rules_lib.gaps(months_since_bankruptcy_or_foreclosure=months_since_bankruptcy_or_foreclosure)
    if missing:
        return rules_lib.unknown(*missing)

    if months_since_bankruptcy_or_foreclosure < 12:
        return False
    if months_since_bankruptcy_or_foreclosure >= 36:
        return True

    loan_purpose = ctx['loan_purpose']
    cltv_pct = ctx['cltv_pct']
    missing = rules_lib.gaps(loan_purpose=loan_purpose, cltv_pct=cltv_pct)
    if missing:
        return rules_lib.unknown(*missing)

    if months_since_bankruptcy_or_foreclosure < 24:
        maximum_cltv = 65
    elif rules_lib.same(loan_purpose, 'purchase'):
        maximum_cltv = 80
    elif rules_lib.same(loan_purpose, 'Refi R/T') or rules_lib.same(loan_purpose, 'Refi C/O'):
        maximum_cltv = 75
    else:
        return rules_lib.unknown('loan_purpose')

    return cltv_pct <= maximum_cltv

