def check(ctx):
    product_raw = ctx['product_is_interest_only']
    missing = rules_lib.gaps(product_is_interest_only=product_raw)
    if missing:
        return rules_lib.unknown(*missing)
    product = rules_lib.flag(product_raw)
    if product is None:
        return rules_lib.unknown('product_is_interest_only')
    if not product:
        return True

    term_raw = ctx['interest_only_10_40']
    amount = ctx['loan_amount']
    fico = ctx['fico']
    first_time_raw = ctx['first_time_homebuyer']
    vacant_raw = ctx['vacant_property']
    listed_raw = ctx['property_currently_listed_for_sale']
    missing = rules_lib.gaps(
        interest_only_10_40=term_raw,
        loan_amount=amount,
        fico=fico,
        first_time_homebuyer=first_time_raw,
        vacant_property=vacant_raw,
        property_currently_listed_for_sale=listed_raw,
    )
    if missing:
        return rules_lib.unknown(*missing)

    term_10_40 = rules_lib.flag(term_raw)
    first_time = rules_lib.flag(first_time_raw)
    vacant = rules_lib.flag(vacant_raw)
    listed = rules_lib.flag(listed_raw)
    if term_10_40 is None:
        return rules_lib.unknown('interest_only_10_40')
    if first_time is None:
        return rules_lib.unknown('first_time_homebuyer')
    if vacant is None:
        return rules_lib.unknown('vacant_property')
    if listed is None:
        return rules_lib.unknown('property_currently_listed_for_sale')

    if amount < 250000 or fico < 640 or first_time or listed:
        return False

    if vacant:
        loan_purpose = ctx['loan_purpose']
        missing = rules_lib.gaps(loan_purpose=loan_purpose)
        if missing:
            return rules_lib.unknown(*missing)
        if rules_lib.same(
            loan_purpose,
            'refinance',
            'rate/term refinance',
            'cash-out refinance',
        ):
            return False

    if term_10_40:
        cltv_pct = ctx['cltv_pct']
        missing = rules_lib.gaps(cltv_pct=cltv_pct)
        if missing:
            return rules_lib.unknown(*missing)
        if cltv_pct > 80 or amount > 3000000:
            return False

    return True

def check(ctx):
    loan_amount = ctx['loan_amount']
    fico = ctx['fico']
    property_type = ctx['property_type']
    property_state = ctx['property_state']
    citizenship_type = ctx['citizenship_type']
    delayed_financing = ctx['delayed_financing']

    missing = rules_lib.gaps(
        loan_amount=loan_amount,
        fico=fico,
        property_type=property_type,
        property_state=property_state,
        citizenship_type=citizenship_type,
        delayed_financing=delayed_financing,
    )
    if missing:
        return rules_lib.unknown(*missing)

    delayed = rules_lib.flag(delayed_financing)
    if delayed is None:
        return rules_lib.unknown('delayed_financing')

    meets = (
        100000 <= loan_amount <= 3000000
        and (loan_amount - 100000) % 50 == 0
        and not rules_lib.same(property_state, 'SD')
        and any(rules_lib.same(property_type, option) for option in (
            'SFR', 'Townhome', 'PUD', 'Warrantable Condo',
            'Non-Warrantable Condo', 'Condotel / PUDtel', '2-4 Units',
            'Manufactured',
        ))
        and any(rules_lib.same(citizenship_type, option) for option in (
            'US Citizen', 'Permanent Resident', 'Non-Permanent Resident',
            'Foreign National', 'ITIN',
        ))
        and (not delayed or loan_amount <= 1500000)
    )

    if loan_amount <= 1500000:
        meets = meets and fico >= 600
    elif loan_amount <= 2000000:
        meets = meets and fico >= 620
    elif loan_amount <= 3000000:
        meets = meets and fico >= 700

    if loan_amount <= 1500000 and fico >= 720:
        loan_purpose = ctx['loan_purpose']
        cltv_pct = ctx['cltv_pct']
        missing = rules_lib.gaps(loan_purpose=loan_purpose, cltv_pct=cltv_pct)
        if missing:
            return rules_lib.unknown(*missing)

        if rules_lib.same(loan_purpose, 'purchase'):
            cltv_limit = 85
        elif rules_lib.same(loan_purpose, 'rate & term') or rules_lib.same(loan_purpose, 'cash-out'):
            cltv_limit = 80
        else:
            return rules_lib.unknown('loan_purpose')
        meets = meets and cltv_pct <= cltv_limit

    return bool(meets)

